import re

def extract_codes(thread):
    codes=set()
    for section in ['emails','drafts']:
        for item in thread.get(section, []) or []:
            body = item.get('body','')
            if body:
                # common: 4-8 digit numeric codes
                for m in re.findall(r'\b\d{4,8}\b', body):
                    codes.add(m)
                # sometimes labeled 'code: ABC123'
                for m in re.findall(r'code\s*[:\-]?\s*([A-Za-z0-9]{4,12})', body, flags=re.I):
                    codes.add(m)
    return sorted(codes)

